    [15449]={name="Ghastly Trousers",quality=2,ilvl=18,reqLevel=9,sourceType="quest_reward",instructions="Reward from the quest 'The Power to Destroy...'. Pick it over the other reward choices. Starts with Varimathras in Undercity. Objective: Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity.",zone="Ragefire Chasm",questName="The Power to Destroy...",lore="Many denizens of the Legion bestow gifts on their followers as you may well know. Some of these gifts the Dark Lady feels would be better off in her hands than in the hands of those with..."},
    [15452]={name="Featherbead Bracers",quality=2,ilvl=18,reqLevel=9,sourceType="quest_reward",instructions="Reward from the quest 'Returning the Lost Satchel'. Pick it over the other reward choices. Starts with Maur Grimtotem in Thunder Bluff. Objective: Take the Grimtotem Satchel to Rahauro in Thunder Bluff.",zone="Ragefire Chasm",questName="Returning the Lost Satchel",lore="You find a satchel under the body of the tauren. It is still gripped tightly in his arms as though he was trying to protect it while being attacked by the troggs."},
