    [16604]={name="Moon Robes of Elune",quality=2,ilvl=10,reqLevel=5,sourceType="quest_reward",instructions="Reward from the quest 'Garments of the Moon'. Starts with Laurna Morninglight in Teldrassil. Objective: Find Sentinel Shaya and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Laurna Morninglight in Dolanaar.",zone="Teldrassil",questName="Garments of the Moon",lore="This will at least protect her from harm longer if she finds trouble. Return to me here after you've done your duty to Elune."},
    [16605]={name="Friar's Robes of the Light",quality=2,ilvl=5,reqLevel=5,sourceType="quest_reward",instructions="Reward from the quest 'Garments of the Light'. Starts with Maxan Anvol in Dun Morogh. Objective: Find Mountaineer Dolf and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Maxan Anvol in Kharanos.",zone="Dun Morogh",questName="Garments of the Light",lore="Normally I put forth a small challenge to followers of the Light to test their skill."},
    [16606]={name="Juju Hex Robes",quality=2,ilvl=5,reqLevel=5,sourceType="quest_reward",instructions="Reward from the quest 'Garments of Spirituality'. Starts with Tai'jin in Durotar. Objective: Find Grunt Kor'ja and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Tai'jin at Razor Hill.",zone="Durotar",questName="Garments of Spirituality",lore="You be ready for your first test. South of Razor Hill, just outta town, one of our grunts be hurt fightin' off some o' Proudmoore's old troops."},
    [16607]={name="Acolyte's Sacrificial Robes",quality=2,ilvl=5,reqLevel=5,sourceType="quest_reward",instructions="Reward from the quest 'Garments of Darkness'. Starts with Dark Cleric Beryl in Tirisfal Glades. Objective: Find Deathguard Kel and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Dark Cleric Beryl in Brill.",zone="Tirisfal Glades",questName="Garments of Darkness",lore="Our power comes from darkness and shadow, but that is not your only role. You have acknowledged that there is merit in knowing the healing arts."},
